DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('app_private.create_donor_request(uuid,text,text,date)'::regprocedure) INTO d; d:=replace(d,' AND om.is_active',''); EXECUTE d; END $$;
DROP POLICY IF EXISTS "Donors view their sponsorship updates" ON public.sponsorship_updates;
CREATE POLICY "Donors view their sponsorship updates" ON public.sponsorship_updates FOR SELECT TO authenticated USING (visible_to_donor AND approved_at IS NOT NULL AND deleted_at IS NULL AND EXISTS(SELECT 1 FROM public.donor_accounts a JOIN public.beneficiary_donors b ON b.organization_id=a.organization_id AND b.donor_name=a.donor_name WHERE a.user_id=auth.uid() AND a.is_active AND a.organization_id=sponsorship_updates.organization_id AND b.beneficiary_id=sponsorship_updates.beneficiary_id AND (sponsorship_updates.donor_name IS NULL OR sponsorship_updates.donor_name=a.donor_name) AND (sponsorship_updates.contribution_id IS NULL OR EXISTS(SELECT 1 FROM public.donations d WHERE d.id=sponsorship_updates.contribution_id AND d.donor_account_id=a.id))));
NOTIFY pgrst,'reload schema';